// photoassets.js — THE PHOTOS CARD'S PICTURES ARE THE FOLDERS' CONTENTS
//
//   src/assets/photos/reel/          the pictures of his life
//   src/assets/photos/photography/   the photography
//
// This file used to be GENERATED by tools/bake_photos.mjs: a few hundred
// `import x from "...?url"` lines, one per file. Delete a file and the import
// pointed at nothing, and Vite took the whole site down with "Failed to resolve
// import" -- a list that had to be kept in step with a folder by a tool.
//
// Now the folder is the list. `import.meta.glob` is resolved by Vite from
// whatever is on disk when it runs, so a picture removed is simply not in the
// list, and a picture dropped in is in it -- nothing to run, nothing to edit,
// nothing to go stale. (The bake still exists, but only for what a browser
// cannot show: it turns an iPhone's HEIC into WebP and writes it here. It no
// longer writes any code.)
//
// A FILE'S NAME CARRIES ITS SHAPE:  <id>_<width>x<height>_<edge>.webp
//   img-0598_1536x2048_l12_640.webp   the same picture at three long edges:
//   img-0598_1536x2048_l12_1280.webp  640 / 1280 / 2048, all of them optional
//   img-0598_1536x2048_l12_2048.webp
// (l12 is how light it is, 0-100, measured by the bake: the page puts the
// bright pictures where it wants something large, and only ever compares one
// picture with the others, so a night set and a day set both work. Optional.)
// The page has to know a picture's shape BEFORE it arrives, or everything
// under it moves when it does; a name is the one place a shape can live that
// cannot go stale and is not a second file to keep. A file without a shape in
// its name (a picture dropped in by hand) still works: it is taken as 3:4
// until the browser has read the real one (`guess`), and the page corrects
// itself then.
//
// `collect` is pure -- it takes the glob's record -- so it is checked in node.

const NAME = /^(.+?)(?:_(\d+)x(\d+))?(?:_l(\d{1,3}))?(?:_(\d{3,4}))?\.(?:webp|jpe?g|png|avif)$/i;

/**
 * @param files  { "../assets/photos/reel/x_1x1_640.webp": url, ... }
 * @returns [{ id, w, h, l, guess, src: { [edge]: url } }] in a stable order (by id); l is 0-1 or 0.5 unknown
 */
export function collect(files) {
  const by = new Map();
  for (const [path, url] of Object.entries(files || {})) {
    const name = path.slice(path.lastIndexOf("/") + 1);
    const m = NAME.exec(name);
    if (!m || name.startsWith(".")) continue;
    const [, id, w, h, l, edge] = m;
    const p = by.get(id) || by.set(id, { id, w: 0, h: 0, l: 0.5, guess: true, src: {} }).get(id);
    if (l !== undefined) p.l = Math.min(100, +l) / 100;
    if (w && h) { p.w = Math.max(p.w, +w); p.h = Math.max(p.h, +h); p.guess = false; }
    // a copy with no edge in its name is the only one there is: call it by its
    // own long edge if the name gave a shape, or 1280 if it did not
    p.src[edge ? +edge : (w && h ? Math.max(+w, +h) : 1280)] = url;
  }
  const out = [...by.values()];
  for (const p of out) if (p.guess) { p.w = 3; p.h = 4; }
  return out.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

/** the copies of a picture, smallest first: [[edge, url], ...] */
export const copies = (p) => Object.entries(p.src).map(([e, u]) => [Number(e), u]).sort((a, b) => a[0] - b[0]);
/** the copy nearest to (and not under) a wanted long edge; the largest if none is */
export const copyFor = (p, edge) => {
  const list = copies(p);
  return (list.find(([e]) => e >= edge) || list[list.length - 1])[1];
};

// ── THE ARRANGEMENT: WHICH PICTURE IS IN WHICH FRAME ──────────────────────
// The page lays itself out from the pictures (photolayout.js), so each picture
// has a frame of its own shape, in a place that follows from the whole set.
// That is the default and needs nothing. To MOVE a picture, the editor swaps
// two pictures over: each keeps the frame it was in, the frames keep their
// sizes, and the picture is cropped to the other one's frame (object-fit:
// cover). What it saves is  src/assets/photos/arrangement.json :
//
//   { "photography": { "<frame>": "<picture shown in it>", ... }, "reel": { ... } }
//
// A FRAME IS NAMED BY THE PICTURE IT WAS MADE FOR, which is why this survives
// the folders changing. A picture added is in its own frame; one removed takes
// its frame with it (the layout is worked out again without it) and any frame
// that was showing it goes back to its own picture. The file is optional: it is
// read through a glob, so a missing one is the default arrangement and not an
// error, and an entry naming a picture that is gone is ignored. `arrange` is
// pure, so it is checked in node.
const NAMEOK = /^[A-Za-z0-9._-]+$/;
/** whatever was in the file -> { photography: {frame: shown}, reel: {...} }, only well-formed entries that move something */
export function sanitize(raw) {
  const out = { photography: {}, reel: {} };
  for (const set of Object.keys(out)) {
    const m = raw && typeof raw === "object" ? raw[set] : null;
    if (m && typeof m === "object") {
      for (const [k, v] of Object.entries(m)) if (typeof v === "string" && NAMEOK.test(k) && NAMEOK.test(v) && k !== v) out[set][k] = v;
    }
  }
  return out;
}

/**
 * Who is shown in whose frame. Every picture is shown exactly once, in every
 * case: an entry is honoured if both ends exist and the picture is not already
 * placed; a frame left without one gets its own picture if that is free, and
 * otherwise the first picture nobody has been given.
 * @param list  the pictures of one set (collect's output)
 * @param map   { frameId: shownId }
 * @returns Map frameId -> picture
 */
export function arrange(list, map = {}) {
  const by = new Map(list.map((p) => [p.id, p]));
  const shown = new Map(), used = new Set();
  for (const f of list) {
    const want = map && map[f.id];
    if (want && want !== f.id && by.has(want) && !used.has(want)) { shown.set(f.id, by.get(want)); used.add(want); }
  }
  for (const f of list) if (!shown.has(f.id) && !used.has(f.id)) { shown.set(f.id, f); used.add(f.id); }
  const spare = list.filter((p) => !used.has(p.id));
  for (const f of list) if (!shown.has(f.id)) { const p = spare.shift(); shown.set(f.id, p); used.add(p.id); }
  return shown;
}

/** a full { frame: shown } map -> only the entries that move something (what the file keeps) */
export const compact = (full) => Object.fromEntries(Object.entries(full || {}).filter(([k, v]) => k !== v));

// (a glob's pattern has to be a literal, so the extensions are written twice)
export const REEL = collect(import.meta.glob("../assets/photos/reel/*.{webp,jpg,jpeg,png,avif}", { eager: true, query: "?url", import: "default" }));
export const PHOTOGRAPHY = collect(import.meta.glob("../assets/photos/photography/*.{webp,jpg,jpeg,png,avif}", { eager: true, query: "?url", import: "default" }));
// the About card's binder pages, in file-name order (a page per photograph, one
// side of a sheet each: front, back, next front...), and its portrait
// (2026-10-04). The same folders-are-the-list rule as the two above.
export const BINDER = collect(import.meta.glob("../assets/photos/binder/*.{webp,jpg,jpeg,png,avif}", { eager: true, query: "?url", import: "default" }));
export const PORTRAIT = collect(import.meta.glob("../assets/photos/portrait/*.{webp,jpg,jpeg,png,avif}", { eager: true, query: "?url", import: "default" }));
export const ARRANGEMENT = sanitize(Object.values(import.meta.glob("../assets/photos/arrangement.json", { eager: true, import: "default" }))[0]);
